namespace Ets.Modules.Deals.Domain.ValueObjects;

/// <summary>
///     The identity of a deal: a Guid v7 generated by the domain when the deal is captured (ADR-0014). Also
///     the deal's Marten stream id. People quote a deal by its business reference, never by this id.
/// </summary>
public readonly record struct DealId(Guid Value)
{
    public override string ToString()
    {
        return Value.ToString();
    }
}
